"""matplotlib._blocking_input — synchronous input loop shim.

The plotly backend is non-interactive (no event loop), so ginput /
waitforbuttonpress / blocking selection just return empty / False.
"""


class BlockingInput:
    def __init__(self, fig, eventslist=()): self.fig = fig
    def __call__(self, n=1, timeout=30): return []


class BlockingMouseInput(BlockingInput):
    def __call__(self, n=1, timeout=30, show_clicks=True,
                 mouse_add=1, mouse_pop=3, mouse_stop=2):
        return []


class BlockingKeyMouseInput(BlockingInput):
    def __call__(self, timeout=30):
        return False


# ─── Added: missing public name from upstream _blocking_input.py ───


def blocking_input_loop(figure, event_names, timeout, handler):
    """Block until ``handler`` returns or ``timeout`` seconds elapse.
    Used by ``Figure.waitforbuttonpress`` and ``ginput``. The plotly
    backend doesn't run a GUI event loop, so we just call the handler
    once and return."""
    try:
        handler(None)
    except Exception:
        pass
